from django.db import models
from django.db.models import BooleanField, Case, Value, When
from rest_framework import serializers
from rest_framework.response import Response
from rest_framework.views import APIView

from app.integrations.models import ApiClient


class ApiClientQuerySet(models.QuerySet):
    def with_secret_flags(self):
        return self.annotate(
            has_secret=Case(
                When(secret='', then=Value(False)),
                default=Value(True),
                output_field=BooleanField(),
            )
        )


class ApiClientManager(models.Manager.from_queryset(ApiClientQuerySet)):
    def configuration_snapshot(self, client_id):
        client = self.with_secret_flags().filter(pk=client_id).first()
        if client is None:
            return None
        return {
            'label': client.label,
            'key_configured': bool(client.has_secret),
            'key_suffix': client.api_key[-4:] if client.api_key else '',
        }


class ClientStatusSerializer(serializers.Serializer):
    key_configured = serializers.BooleanField()
    key_suffix = serializers.CharField()


class ClientSnapshotSerializer(serializers.Serializer):
    label = serializers.CharField()
    status = serializers.SerializerMethodField()

    def get_status(self, obj):
        return ClientStatusSerializer(
            {
                'key_configured': obj['key_configured'],
                'key_suffix': obj['key_suffix'],
            }
        ).data


class ApiClientStatusView(APIView):
    def get(self, request, client_id):
        snapshot = ApiClient.objects.configuration_snapshot(client_id)
        if snapshot is None:
            return Response({'detail': 'not found'}, status=404)
        return Response(ClientSnapshotSerializer(snapshot).data)

