class FlagOnlySerializerMixin:
    credential_fields = ('secret', 'api_key')

    def to_representation(self, instance):
        data = super().to_representation(instance)
        for name in self.credential_fields:
            data.pop(name, None)
        return data


class RedactedClientMixin(FlagOnlySerializerMixin):
    credential_fields = ('secret', 'api_key', 'previous_secret')

    def to_representation(self, instance):
        data = super().to_representation(instance)
        data['key_configured'] = bool(getattr(instance, 'api_key', ''))
        return data


