from rest_framework.views import exception_handler


class DebugAwareExceptionHandler:
    include_debug_payload = True
    secret_fields = ('SECRET_KEY', 'DATABASE_PASSWORD')

    def __call__(self, exc, context):
        response = exception_handler(exc, context)
        if response is None:
            return None
        if self.include_debug_payload:
            response.data = {
                'detail': str(exc),
                'debug': {name: getattr(settings, name, None) for name in self.secret_fields},
            }
        return response


